  "Connect your agents": "Hubungkan agen kamu",
  "Ramu runs the coding agents you already use, signed in with your own accounts.": "Ramu menjalankan agen coding yang sudah kamu pakai, masuk dengan akunmu sendiri.",
  "Choose how you pick models": "Pilih cara memilih model",
  "Pick the control the model bar shows. Try each example; you can switch any time.": "Pilih kontrol yang tampil di bilah model. Coba tiap contoh; kamu bisa menggantinya kapan saja.",
  "Choose what agents do on their own": "Pilih yang dikerjakan agen sendiri",
