  "Example": "Contoh",
  "One slider moves through saved steps, from a quick, cheap model to a slower, thorough one. Best when you switch models often.": "Satu slider berpindah antar langkah tersimpan, dari model cepat dan murah ke model yang lebih lambat dan teliti. Cocok jika kamu sering berganti model.",
