  "Example effort": "Contoh effort",
  "Higher steps and effort give better answers on hard work but use more tokens and take longer.": "Langkah dan effort yang lebih tinggi memberi jawaban lebih baik untuk pekerjaan sulit, tetapi memakai lebih banyak token dan lebih lama.",
