  "Devices on this Wi-Fi or your VPN (such as Tailscale) connect directly after pairing. Not encrypted by Ramu, so use a network you trust.": "Perangkat di Wi-Fi ini atau VPN-mu (seperti Tailscale) terhubung langsung setelah dipasangkan. Tidak dienkripsi oleh Ramu, jadi pakai jaringan yang kamu percaya.",
  "Pair a phone or another computer from Settings › Remote access whenever you are ready.": "Pasangkan ponsel atau komputer lain dari Pengaturan › Akses jarak jauh kapan pun kamu siap.",
  "Add another repository": "Tambah repositori lain",
