  'Let other devices use this host': 'Biarkan perangkat lain memakai host ini',
  'Link, address or SSH': 'Tautan, alamat, atau SSH',
  'Link, address or SSH host': 'Tautan, alamat, atau host SSH',
  'Local network or VPN': 'Jaringan lokal atau VPN',
  'More for {0}': 'Lainnya untuk {0}',
  'Nearby': 'Terdekat',
  'Not allowed: {0}': 'Belum diizinkan: {0}',
  'On that host, open Remote access and choose Pair a device. Paste its link, or type its address and code.': 'Di host itu, buka Akses jarak jauh lalu pilih Pasangkan perangkat. Tempel tautannya, atau ketik alamat dan kodenya.',
  'Pair {0} again': 'Pasangkan {0} lagi',
  'Pairing link, 100.64.0.7:7788 or user@host': 'Tautan pemasangan, 100.64.0.7:7788, atau user@host',
  'Pause connection': 'Jeda koneksi',
  'Waiting for {0} to allow it': 'Menunggu {0} mengizinkannya',
  'Waiting for {0} to allow {1}': 'Menunggu {0} mengizinkan {1}',
  'What this device may do there': 'Yang boleh dilakukan perangkat ini di sana',
  'Show full report': 'Lihat laporan lengkap',
  'Connect to {0}?': 'Sambungkan ke {0}?',
  'Invitation sent to {0}': 'Undangan terkirim ke {0}',
  'Let {0} connect here?': 'Izinkan {0} tersambung ke sini?',
  'Let {0} connect here…': 'Izinkan {0} tersambung ke sini…',
  'Not now': 'Nanti saja',
  'Ramu asks on {0}. Once its owner connects, it appears under Devices that can use this host, where you can revoke it.': 'Ramu bertanya di {0}. Setelah pemiliknya menyambung, host itu muncul di Perangkat yang bisa memakai host ini, tempat kamu bisa mencabutnya.',
  'Send invitation': 'Kirim undangan',
  'This computer has no address another host can reach yet.': 'Komputer ini belum punya alamat yang bisa dijangkau host lain.',
  'Update Ramu on {0} to use this.': 'Perbarui Ramu di {0} untuk memakai ini.',
  '{0} invites this computer to connect back, so you can open its threads, files and terminals from here too. It joins Hosts you use; you can forget it any time.': '{0} mengundang komputer ini untuk menyambung balik, jadi kamu juga bisa membuka thread, file, dan terminalnya dari sini. Host itu masuk ke Host yang kamu pakai; kamu bisa melupakannya kapan saja.',
  '{0} will be able to open this computer’s threads, files and terminals, with full access. Ramu asks on {0} first; nothing connects until its owner accepts.': '{0} akan bisa membuka thread, file, dan terminal komputer ini dengan akses penuh. Ramu bertanya di {0} dulu; tidak ada yang tersambung sampai pemiliknya menerima.',
  'Change it in Ramu on that Mac; it asks for that Mac’s administrator password.': 'Ubah di Ramu pada Mac itu; Mac itu akan meminta kata sandi administratornya.',
  'Enter the administrator password in the prompt on this Mac. It can open behind other windows.': 'Masukkan kata sandi administrator di prompt pada Mac ini. Prompt itu bisa terbuka di belakang jendela lain.',
  'Setup stopped: {0}': 'Penyiapan berhenti: {0}',
  'Almost done: {0}': 'Hampir selesai: {0}',
  'Open permission setup': 'Buka penyiapan izin',
  'Keep working while the screen is locked?': 'Tetap bekerja saat layar terkunci?',
  'This Mac is showing its login window, so its apps cannot be used from Ramu: macOS lets only system software, such as Screen Sharing, sign in there. Sign in at the Mac or with Screen Sharing, then try again.':
    'Mac ini sedang menampilkan jendela login, jadi aplikasinya tidak bisa dipakai dari Ramu: macOS hanya mengizinkan perangkat lunak sistem, seperti Berbagi Layar, untuk masuk di sana. Masuk di Mac atau lewat Berbagi Layar, lalu coba lagi.',
  'This Mac is showing its login window, so its main display cannot be seen or controlled from Ramu: macOS lets only system software, such as Screen Sharing, type there. Sign in at the Mac or with Screen Sharing, then open the display again.':
    'Mac ini sedang menampilkan jendela login, jadi layar utamanya tidak bisa dilihat atau dikendalikan dari Ramu: macOS hanya mengizinkan perangkat lunak sistem, seperti Berbagi Layar, mengetik di sana. Masuk di Mac atau lewat Berbagi Layar, lalu buka layar lagi.',
  'This Mac is locked, so its main display cannot be seen or controlled. Unlock it, or allow one app instead: with “Keep working while the screen is locked” on, work in an app continues behind the lock screen.': 'Mac ini terkunci, jadi layar utamanya tidak bisa dilihat atau dikendalikan. Buka kuncinya, atau izinkan satu aplikasi saja: dengan “Tetap bekerja saat layar terkunci” menyala, pekerjaan di aplikasi itu berlanjut di balik layar kunci.',
  'This Mac is locked, so its main display cannot be used. Allow one app: with “Keep working while the screen is locked” on, the agent works in it behind the lock screen.': 'Mac ini terkunci, jadi layar utamanya tidak bisa dipakai. Izinkan satu aplikasi: dengan “Tetap bekerja saat layar terkunci” menyala, agen bekerja di aplikasi itu di balik layar kunci.',
  'Show threads from': 'Tampilkan thread dari',
  '{0} connected · {1} hosts': '{0} tersambung · {1} host',
  'Turn off to pause this connection without forgetting it.': 'Matikan untuk menjeda koneksi ini tanpa melupakannya.',
  'Copy table': 'Salin tabel',
  'Copy command': 'Salin perintah',
  'Install idb': 'Pasang idb',
  'Watching works. To let agents tap and type, install idb.': 'Menonton sudah bisa. Agar agent bisa mengetuk dan mengetik, pasang idb.',
  'Tapping an iOS Simulator needs idb. Install it in Settings › Computer use › Test devices.': 'Mengetuk iOS Simulator memerlukan idb. Pasang di Pengaturan › Penggunaan komputer › Perangkat uji.',
  'Install Homebrew from brew.sh first, then try again.': 'Pasang Homebrew dari brew.sh terlebih dahulu, lalu coba lagi.',
  'Install the Xcode command line tools with xcode-select --install, then try again.': 'Pasang Xcode command line tools dengan xcode-select --install, lalu coba lagi.',
  'idb installation is already running.': 'Pemasangan idb sedang berjalan.',
  'Install idb on the owning host.': 'Pasang idb di host pemilik.',
  'idb installed without its executables. Try again.': 'idb terpasang tanpa file yang bisa dijalankan. Coba lagi.',
  'Reach Ramu from your other devices': 'Jangkau Ramu dari perangkatmu yang lain',
  'Use your phone or another computer with this host over your network or VPN. You can change this later.': 'Pakai ponsel atau komputer lain dengan host ini lewat jaringan atau VPN-mu. Kamu bisa mengubahnya nanti.',
  'Nothing outside this computer can reach it yet. Turn on Allow other devices in Settings → Remote access; the address then appears here.': 'Belum ada yang bisa menjangkaunya dari luar komputer ini. Nyalakan Izinkan perangkat lain di Pengaturan → Akses jarak jauh; alamatnya lalu tampil di sini.',
  'Turn on Local network or VPN below first, so {0} can reach this computer.': 'Nyalakan dulu Jaringan lokal atau VPN di bawah, supaya {0} bisa menjangkau komputer ini.',
  'Saved for this thread': 'Tersimpan untuk utas ini',
  'Saved and kept as {0}': 'Tersimpan dan disimpan sebagai {0}',
  'Keep as {0} for later threads': 'Simpan sebagai {0} untuk utas berikutnya',
  'The agent gets a private file with the value, never the value itself. The file is deleted after a day.':
    'Agen hanya menerima berkas pribadi berisi nilainya, bukan nilainya sendiri. Berkas itu dihapus setelah sehari.',
  'Asked for a secret': 'Meminta rahasia',
  'Asking for a secret': 'Meminta rahasia',
  'In a new worktree, with the uncommitted changes': 'Di worktree baru, dengan perubahan yang belum di-commit',
  'Start a new thread on a new branch in its own worktree, with the current conversation and a copy of the uncommitted changes, new files included. This checkout keeps its changes.':
    'Mulai utas baru di branch baru dalam worktree-nya sendiri, dengan percakapan ini dan salinan perubahan yang belum di-commit, termasuk berkas baru. Checkout ini tetap menyimpan perubahannya.',
  'Continue in a new worktree': 'Lanjutkan di worktree baru',
  'Continue in a new worktree?': 'Lanjutkan di worktree baru?',
