  'Set up a provider': 'Siapkan provider',
  'When a thread\'s provider cannot do something, such as making an image, its agent asks Ramu, which runs just that step on one of your signed-in providers that can. Only what the agent passes is sent.': 'Saat provider thread tidak bisa melakukan sesuatu, misalnya membuat gambar, agent-nya meminta Ramu menjalankan langkah itu saja di salah satu provider yang sudah kamu masuki dan bisa melakukannya. Hanya yang diberikan agent yang dikirim.',
  'Checked on {0}': 'Sudah diperiksa di {0}',
  'No signed-in provider here offers it.': 'Belum ada provider yang sudah masuk di sini yang menyediakannya.',
  'Ask before using another provider': 'Tanya sebelum memakai provider lain',
  'Each call that would run on a provider other than the thread’s waits for your approval, which names the provider and what is sent.': 'Setiap panggilan yang akan berjalan di provider selain milik thread menunggu persetujuanmu, yang menyebut provider dan apa yang dikirim.',
  'Checked with one small request on version {0}.': 'Diperiksa dengan satu permintaan kecil pada versi {0}.',
  'Available': 'Tersedia',
  'Scope: the team your projects are in, not Full Account': 'Cakupan: tim tempat proyekmu berada, bukan Full Account',
  'Netlify tokens reach every team you belong to, so choose an expiry': 'Token Netlify menjangkau semua tim yang kamu ikuti, jadi pilih masa berlaku',
  'Pick the workspace your projects are in, so the token reaches only that workspace': 'Pilih workspace tempat proyekmu berada, supaya token hanya menjangkau workspace itu',
  'Create an organization token for the organization your apps go in, rather than a personal access token': 'Buat token organisasi untuk organisasi tempat aplikasimu berada, bukan token akses pribadi',
  '{0} is recommended for this project’s stack.': '{0} disarankan untuk stack proyek ini.',
  'Fly.io cannot watch a repository, so Ramu creates the app, keeps a deploy token limited to it in the repository’s GitHub Actions secrets, and opens a pull request with fly.toml, a Dockerfile when the repository has none, and the deploy job. Every merge to the default branch deploys; there are no preview deployments.': 'Fly.io tidak bisa memantau repositori, jadi Ramu membuat aplikasinya, menyimpan token deploy yang terbatas untuk aplikasi itu di secret GitHub Actions repositori, lalu membuka pull request berisi fly.toml, Dockerfile bila repositori belum punya, dan job deploy. Setiap merge ke branch default akan men-deploy; tidak ada deployment pratinjau.',
  'Set up Fly.io': 'Siapkan Fly.io',
  'Not connected. Deploys and Publish to the web need an account.': 'Belum terhubung. Deploy dan Terbitkan ke web butuh akun.',
  'signed in through its CLI': 'masuk lewat CLI-nya',
  'token saved on this host': 'token disimpan di host ini',
